update platform_pass_order
set xpay_product_id = #{productId}, xpay_offer_id = #{offerId}, xpay_env = #{env}
where id = #{id} and status = 0 and channel = 'XPAY' and xpay_product_id is null

update platform_pass_order set status = 1, refund_no = null, refund_reason = null,
    refund_requested_by = null, refund_requested_time = null
where id = #{id} and status = 4 and refund_no = #{refundNo}

update platform_pass_order
set review_status = #{decision}, review_handler = #{handler}, review_decision = #{note}, review_time = #{time}
where id = #{id} and review_status = 1 and status in (1, 4)

